'use strict';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safe=s=>{try{const u=new URL(s);return ['http:','https:'].includes(u.protocol)?u.href:null;}catch{return null;}};
const link=(url,label,cls='')=>safe(url)?`<a class="${cls}" href="${esc(safe(url))}" target="_blank" rel="noopener">${esc(label)}</a>`:esc(label);
const normalize=s=>String(s).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const format=n=>typeof n==='number'?n.toLocaleString('en-US'):'—';
const date=s=>s?String(s).split('T')[0]:'Not recorded';
let simulators=[],sortKey='stars',direction='desc',expanded=new Set();
const textKeys=['name','description','embodiment','backend'];
const value=(s,key)=>key==='stars'?s.github.stars:key==='citations'?s.paper.citations:key==='release'?s.release.date||null:key==='embodiment'?s.embodiments.join(', '):key==='backend'?s.backends.join(', '):key==='benchmarks'?s.benchmarks.length:s[key];
function compare(a,b){const x=value(a,sortKey),y=value(b,sortKey);if(x==null&&y!=null)return 1;if(y==null&&x!=null)return -1;let diff=0;if(x!=null&&y!=null)diff=typeof x==='number'?x-y:String(x).localeCompare(String(y),'en',{numeric:true,sensitivity:'base'});return diff?(direction==='asc'?diff:-diff):a.name.localeCompare(b.name,'en',{sensitivity:'base'});}
function details(s){const p=s.paper,g=s.github,r=s.release;return `<tr class="detail-row" id="detail-${s.id}"><td colspan="9"><div class="detail-grid"><div><h2>Scope and supported embodiments</h2><p>${esc(s.note)}</p><p>${esc(s.embodiments.join(' · '))}<br><span class="detail-small">Embodiments describe documented model or task support; individual assets and benchmark versions vary.</span></p><h2>Physics backend</h2><p>${esc(s.backends.join(' · '))}</p><h2>Benchmarks in this catalog (${s.benchmarks.length})</h2><div class="benchmark-links">${s.benchmarks.map(b=>`<a href="./#benchmark-${esc(b.id)}" title="${esc(b.note)}">${esc(b.name)}</a>`).join('')}</div><p class="detail-small">Counts include edition-specific, optional, or source-trajectory use. Follow each benchmark for its exact stack and sources.</p><h2>Documentation and evidence</h2><div class="detail-links">${s.sources.map((x,i)=>link(x.url,`Source ${i+1} ↗`)).join('')}<a href="#simulator-${esc(s.id)}">Link to this entry</a></div></div><div><h2>Reference and citations</h2><p>${p.title?link(p.url,p.title):'Software reference; no selected indexed paper'}<br><span class="detail-small">${esc(p.note)}${p.provider?`<br>${esc(p.provider)} · ${format(p.citations)} citations · retrieved ${esc(date(p.retrieved_at))}`:''}</span></p><h2>Repository popularity</h2><p>${link(g.url,g.repository)} · ${format(g.stars)} stars<br><span class="detail-small">${esc(g.scope)}${g.archived?' Repository is archived.':''}<br>Retrieved ${esc(date(g.retrieved_at))} · ${link(g.source_url,'GitHub record ↗')}</span></p><h2>Release milestone</h2><p>${link(r.source_url,r.date||'Unavailable')}<br><span class="detail-small">${esc(r.basis||'No documented milestone recorded.')}</span></p></div></div></td></tr>`;}
function reset(){for(const id of ['query','category','embodiment','simulator'])$(id).value='';}
function render(){const q=normalize($('query').value.trim()),type=$('category').value,emb=$('embodiment').value,backend=$('simulator').value;const rows=simulators.filter(s=>(!type||s.type===type)&&(!emb||s.embodiments.includes(emb))&&(!backend||s.backends.includes(backend))&&(!q||normalize([s.name,s.type,s.description,s.note,...s.embodiments,...s.backends,...s.benchmarks.map(b=>b.name)].join(' ')).includes(q))).sort(compare);
$('results').innerHTML=rows.length?rows.map(s=>`<tr id="simulator-${s.id}" class="benchmark-row ${expanded.has(s.id)?'expanded':''}"><td>${link(s.url,s.name,'name')}<span class="simulator-type">${esc(s.type)}</span></td><td>${esc(s.description)}</td><td class="embodiment-cell">${s.embodiments.map(e=>`<span>${esc(e)}</span>`).join('')}</td><td class="simulator-cell">${s.backends.map(b=>`<span>${esc(b)}</span>`).join('')}</td><td class="date">${link(s.release.source_url,s.release.date||'—')}</td><td class="numeric">${typeof s.paper.citations==='number'?link(s.paper.record_url,format(s.paper.citations)):'<span class="missing" aria-label="Citations unavailable">—</span>'}</td><td class="numeric">${typeof s.github.stars==='number'?link(s.github.url,format(s.github.stars)):'<span class="missing" aria-label="Stars unavailable">—</span>'}</td><td class="numeric"><button type="button" class="count-button" data-detail="${s.id}" aria-expanded="${expanded.has(s.id)}" aria-label="View ${s.benchmarks.length} catalog benchmarks for ${esc(s.name)}">${format(s.benchmarks.length)}</button></td><td><button class="detail-button" type="button" data-detail="${s.id}" aria-expanded="${expanded.has(s.id)}" ${expanded.has(s.id)?`aria-controls="detail-${s.id}"`:''} aria-label="${expanded.has(s.id)?'Hide':'Show'} details for ${esc(s.name)}"><svg width="14" height="14" viewBox="0 0 16 16" aria-hidden="true"><path d="m4 6 4 4 4-4" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg></button></td></tr>${expanded.has(s.id)?details(s):''}`).join(''):'<tr><td colspan="9" class="empty"><p>No matching simulators.</p><button type="button" id="clear">Clear filters</button></td></tr>';
const labels={name:'name',description:'description',embodiment:'embodiment',backend:'physics backend',release:'release date',citations:'citations',stars:'GitHub stars',benchmarks:'catalog benchmark count'};
$('result-count').textContent=`${rows.length} of ${simulators.length} simulators & frameworks · ${labels[sortKey]}, ${textKeys.includes(sortKey)?(direction==='asc'?'A–Z':'Z–A'):sortKey==='release'?(direction==='asc'?'oldest first':'newest first'):(direction==='asc'?'low to high':'high to low')}`;
document.querySelectorAll('th[data-key]').forEach(th=>{const active=th.dataset.key===sortKey;th.setAttribute('aria-sort',active?(direction==='asc'?'ascending':'descending'):'none');th.querySelector('span').textContent=active?(direction==='asc'?'↑':'↓'):'↕';});$('clear')?.addEventListener('click',()=>{reset();render();$('query').focus();});}
function deepLink(){const id=location.hash.replace(/^#simulator-/,'');if(!location.hash.startsWith('#simulator-')||!simulators.some(s=>s.id===id))return;reset();expanded.add(id);render();$('simulator-'+id).scrollIntoView({block:'start'});}
function options(id,tags,label){$(id).innerHTML=`<option value="">${label}</option>`+[...new Set(simulators.flatMap(s=>tags(s)))].sort().map(t=>`<option value="${esc(t)}">${esc(t)} (${simulators.filter(s=>tags(s).includes(t)).length})</option>`).join('');}
async function init(){try{const r=await fetch('simulators.json');if(!r.ok)throw Error();const d=await r.json();simulators=d.simulators;options('category',s=>[s.type],'All types');options('embodiment',s=>s.embodiments,'All embodiments');options('simulator',s=>s.backends,'All backends');$('filters').addEventListener('submit',e=>e.preventDefault());$('query').addEventListener('input',render);for(const id of ['category','embodiment','simulator'])$(id).addEventListener('change',render);document.querySelectorAll('[data-sort]').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.sort;direction=key===sortKey?(direction==='asc'?'desc':'asc'):(textKeys.includes(key)?'asc':'desc');sortKey=key;render();}));$('results').addEventListener('click',e=>{const b=e.target.closest('[data-detail]');if(!b)return;const id=b.dataset.detail,isCount=b.classList.contains('count-button');expanded.has(id)?expanded.delete(id):expanded.add(id);render();document.querySelector(`.${isCount?'count-button':'detail-button'}[data-detail="${id}"]`).focus({preventScroll:true});});render();deepLink();window.addEventListener('hashchange',deepLink);}catch{$('result-count').textContent='The simulator data could not load.';$('results').innerHTML='<tr><td colspan="9" class="empty">Reload the page to try again.</td></tr>';}}
init();
